steps.message:
The rate/search metrics are clean. Let me verify that every service's endpoints actually map to the correct pods — a mismatched selector or port would be a silent fault.

```bash
kubectl get svc,endpoints -n hotel-reservation -o json | python3 -c "
import json,sys
d=json.load(sys.stdin)
svcs={}
for i in d['items']:
    if i['kind']=='Service':
        svcs[i['metadata']['name']]=(i['spec'].get('selector'), [(p['name'],p['port'],p.get('targetPort')) for p in i['spec']['ports']])
    else:
        name=i['metadata']['name']
        subs=[]
        for s in i.get('subsets',[]):
            for a in s.get('addresses',[]):
                for p in s['ports']:
                    subs.append((a['ip'], p['port']))
        if name in svcs:
            print(name, '| selector:', svcs[name][0], '| ports:', svcs[name][1], '| endpoints:', subs)
"; echo === POD IPS ===; kubectl get pods -n hotel-reservation -o custom-columns='NAME:.metadata.name,IP:.status.podIP,LABELS:.metadata.labels'
```

